import{_ as e,o as a,c as l,a2 as r}from"./chunks/framework.BQ1gajhD.js";const f=JSON.parse('{"title":"华熙live五棵松","description":"","frontmatter":{},"headers":[],"relativePath":"landmarks/huaxi.md","filePath":"landmarks/huaxi.md","lastUpdated":1787033866000}'),n={name:"landmarks/huaxi.md"};function d(o,t,i,s,h,g){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="华熙live五棵松" tabindex="-1">华熙live五棵松 <a class="header-anchor" href="#华熙live五棵松" aria-label="Permalink to &quot;华熙live五棵松&quot;">​</a></h1><p><img src="https://images.unsplash.com/photo-1516450360452-9312f5e86fc7?w=1200" alt="华熙live五棵松"></p><blockquote><p>&quot;文体娱乐一站体验。&quot;</p></blockquote><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>华熙LIVE·五棵松位于北京市海淀区复兴路，以五棵松体育馆（凯迪拉克中心）为核心，是集体育赛事、文艺演出、餐饮美食、潮流购物于一体的综合性文体商业街区。这里每年举办大量演唱会、赛事与演出，配套的街区餐饮、酒吧和特色夜市氛围浓厚，是北京西城与海淀一带人气最旺的夜生活与娱乐地标。</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">项目</th><th style="text-align:left;">内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>开放时间</strong></td><td style="text-align:left;">街区全天开放（商户及演出按时段）</td></tr><tr><td style="text-align:left;"><strong>门票价格</strong></td><td style="text-align:left;">街区免费，演出赛事另购票</td></tr><tr><td style="text-align:left;"><strong>建议游玩</strong></td><td style="text-align:left;">2-4小时</td></tr><tr><td style="text-align:left;"><strong>最佳季节</strong></td><td style="text-align:left;">四季皆宜，夜晚最佳</td></tr><tr><td style="text-align:left;"><strong>交通方式</strong></td><td style="text-align:left;">地铁1号线五棵松站</td></tr><tr><td style="text-align:left;"><strong>地址</strong></td><td style="text-align:left;">北京市海淀区复兴路69号</td></tr></tbody></table><h2 id="核心特色" tabindex="-1">核心特色 <a class="header-anchor" href="#核心特色" aria-label="Permalink to &quot;核心特色&quot;">​</a></h2><h3 id="文体演出中心" tabindex="-1">文体演出中心 <a class="header-anchor" href="#文体演出中心" aria-label="Permalink to &quot;文体演出中心&quot;">​</a></h3><p>凯迪拉克中心（五棵松体育馆）是京城顶级演出场馆，常年举办演唱会、篮球赛等大型活动，追星看赛必到。</p><h3 id="活力街区" tabindex="-1">活力街区 <a class="header-anchor" href="#活力街区" aria-label="Permalink to &quot;活力街区&quot;">​</a></h3><p>围绕场馆的街区汇集餐厅、酒吧、咖啡馆与特色小店，营造出年轻化的街区氛围。</p><h3 id="夜间经济" tabindex="-1">夜间经济 <a class="header-anchor" href="#夜间经济" aria-label="Permalink to &quot;夜间经济&quot;">​</a></h3><p>华熙LIVE的夜生活十分丰富，夜市、酒吧、街头表演与灯光景观让夜晚同样精彩。</p><h2 id="游览攻略" tabindex="-1">游览攻略 <a class="header-anchor" href="#游览攻略" aria-label="Permalink to &quot;游览攻略&quot;">​</a></h2><h3 id="推荐路线" tabindex="-1">推荐路线 <a class="header-anchor" href="#推荐路线" aria-label="Permalink to &quot;推荐路线&quot;">​</a></h3><p><strong>半日路线</strong>：</p><p>五棵松站 → 街区散步 → 餐饮美食 → 看一场演出或赛事 → 夜晚街区漫步</p><h3 id="实用贴士" tabindex="-1">实用贴士 <a class="header-anchor" href="#实用贴士" aria-label="Permalink to &quot;实用贴士&quot;">​</a></h3><ol><li><strong>交通</strong>：地铁1号线五棵松站直达</li><li><strong>演出</strong>：热门演出与赛事需提前购票，注意场馆入场时间</li><li><strong>餐饮</strong>：街区餐饮选择丰富，演出散场后人气更旺</li><li><strong>搭配</strong>：与首钢园、北京冬奥公园等西部景点联动游玩</li></ol><h3 id="交通方式" tabindex="-1">交通方式 <a class="header-anchor" href="#交通方式" aria-label="Permalink to &quot;交通方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">方式</th><th style="text-align:left;">路线</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>地铁</strong></td><td style="text-align:left;">1号线五棵松站</td></tr><tr><td style="text-align:left;"><strong>公交</strong></td><td style="text-align:left;">复兴路沿线多路公交</td></tr><tr><td style="text-align:left;"><strong>自驾</strong></td><td style="text-align:left;">定位&quot;华熙LIVE·五棵松&quot;，有配套停车场</td></tr></tbody></table><h2 id="周边景点" tabindex="-1">周边景点 <a class="header-anchor" href="#周边景点" aria-label="Permalink to &quot;周边景点&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">景点</th><th style="text-align:center;">距离</th><th style="text-align:left;">特色</th></tr></thead><tbody><tr><td style="text-align:left;">北京冬奥公园</td><td style="text-align:center;">车程15分钟</td><td style="text-align:left;">滨河体育公园</td></tr><tr><td style="text-align:left;">首钢园</td><td style="text-align:center;">车程20分钟</td><td style="text-align:left;">工业遗存与滑雪大跳台</td></tr><tr><td style="text-align:left;">玉渊潭公园</td><td style="text-align:center;">车程15分钟</td><td style="text-align:left;">樱花与湖景</td></tr><tr><td style="text-align:left;">颐和园</td><td style="text-align:center;">车程25分钟</td><td style="text-align:left;">皇家园林</td></tr></tbody></table><h2 id="文化意义" tabindex="-1">文化意义 <a class="header-anchor" href="#文化意义" aria-label="Permalink to &quot;文化意义&quot;">​</a></h2><p>华熙LIVE·五棵松探索了&quot;文体+商业&quot;的复合型街区模式，把体育场馆单一的功能延伸为全天候的城市娱乐空间，成为北京西部的文化体育消费中心。</p><hr><p><strong>📍 地址</strong>：北京市海淀区复兴路69号 <strong>🚇 地铁</strong>：1号线五棵松站</p><p><strong>💡 Tips</strong>：想追星看演出前先查好场馆排期，演出日周边人流量大，建议早到。</p>',29)])])}const c=e(n,[["render",d]]);export{f as __pageData,c as default};
